module BookNotesHelper
  def book_note_body_html(note, editor: false, images: note.images_for_body(allow_temporary: editor))
    fragment = note.editable_body.fragment
    unless editor
      # Sanitize the saved HTML before adding gallery controls generated by the app.
      body = sanitize(fragment.to_html, tags: sanitizer_allowed_tags,
        attributes: sanitizer_allowed_attributes + [ BookNote::IMAGE_ATTRIBUTE ])
      fragment = ActionText::Fragment.wrap(body)
    end

    fragment = fragment.replace(BookNote::ATTACHMENT_SELECTOR) do |node|
      image = images[BookNote.image_id(node[BookNote::IMAGE_ATTRIBUTE])]
      next "" unless image

      path = book_book_note_image_path(note.user_book.book_id, image)
      if editor
        ActionText::TrixAttachment.from_attributes(book_note_image_id: image.id, content_type: "image/webp", url: path, alt: t("book_notes.image_alt"))
      else
        preview_path = book_book_note_image_path(note.user_book.book_id, image, size: :body)
        thumbnail = image_tag(preview_path, alt: t("book_notes.image_alt"), loading: :lazy, decoding: :async, draggable: false)
        tag.figure(class: "book-note-image") do
          tag.button(thumbnail, type: "button", aria: { label: t("book_notes.open_image"), haspopup: "dialog" },
            data: { photo_gallery_target: "thumbnail", gallery_url: path,
              action: "photo-gallery#open contextmenu->photo-gallery#prevent dragstart->photo-gallery#prevent" })
        end
      end
    end

    return fragment.to_html.html_safe unless editor

    sanitize(fragment.to_html, tags: sanitizer_allowed_tags, attributes: sanitizer_allowed_attributes + [ "data-trix-attachment" ])
  end
end
